CREATE TABLE purchase_order_item (id BIGINT NOT NULL AUTO_INCREMENT,order_id BIGINT NOT NULL,edition_id BIGINT NOT NULL,game_id BIGINT NOT NULL,game_slug_snapshot VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,game_name_snapshot VARCHAR(160) NOT NULL,edition_code_snapshot VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,edition_name_snapshot VARCHAR(160) NOT NULL,unit_price_minor BIGINT NOT NULL,quantity INT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_purchase_order_item UNIQUE(order_id),KEY idx_purchase_order_item_edition(edition_id),KEY idx_purchase_order_item_game(game_id),CONSTRAINT ck_purchase_order_item_price CHECK(unit_price_minor>=0),CONSTRAINT ck_purchase_order_item_quantity CHECK(quantity=1),CONSTRAINT fk_purchase_order_item_order FOREIGN KEY(order_id) REFERENCES purchase_order(id) ON DELETE CASCADE,CONSTRAINT fk_purchase_order_item_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE RESTRICT,CONSTRAINT fk_purchase_order_item_game FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
